static calculateTimeComplexity(
    loopDepth: number,
    hasRecursion: boolean,
    isBinaryRecursion: boolean,
    hasSorting: boolean,
    hasLinearSearch: boolean,
    hasDeepClone: boolean,
    hasAccumulation: boolean
  ): CalculatorComplexityResult {
    const flags: string[] = [];

    // --- 1. FACTORIAL GROWTH (O(n!)) ---
    // Recursion combined with loops or permutations
    if (hasRecursion && loopDepth >= 1 && (hasSorting || isBinaryRecursion)) {
      flags.push("FACTORIAL_EXPLOSION");
      return { notation: "O(n!)", confidence: 70, flags };
    }

    // --- 2. EXPONENTIAL GROWTH (O(2^n)) ---
    if (isBinaryRecursion || (hasRecursion && hasDeepClone)) {
      flags.push("EXPONENTIAL_RECURSION");
      return { notation: "O(2^n)", confidence: 85, flags };
    }

    // --- 3. UNKNOWN HIGH POLYNOMIAL (O(n^k)) ---
    // Depth 4+ is usually the threshold where we stop precise naming
    if (loopDepth >= 4) {
      flags.push("DEEP_NESTING_EXCESSIVE");
      return { notation: "O(n^k)", confidence: 90, flags };
    }

    // --- 4. CUBIC GROWTH (O(n³)) ---
    // Depth 3, or Depth 2 with heavy operations like sorting
    if (loopDepth === 3 || (loopDepth === 2 && hasSorting)) {
      flags.push("CUBIC_COMPLEXITY");
      return { notation: "O(n³)", confidence: 80, flags };
    }

    // --- 5. QUADRATIC GROWTH (O(n²)) ---
    // Depth 2, or Depth 1 with Linear Search/Sorting/Deep Clone
    if (loopDepth === 2) {
      flags.push("NESTED_LOOPS");
      return { notation: "O(n²)", confidence: 95, flags };
    }

    if (loopDepth === 1 && (hasLinearSearch || hasSorting || hasDeepClone)) {
      flags.push("SEARCH_OR_SORT_IN_LOOP");
      // O(n * log n) or O(n * n) both map here for safety
      return { notation: "O(n²)", confidence: 85, flags };
    }

    // --- 6. SUPERLINEAR (O(n log n)) ---
    if (hasSorting) {
      flags.push("SORTING_ALGORITHM");
      return { notation: "O(n log n)", confidence: 95, flags };
    }

    // --- 7. LINEAR (O(n)) ---
    if (loopDepth === 1 || hasLinearSearch || hasRecursion || hasAccumulation) {
      if (hasRecursion) flags.push("RECURSIVE_WALK");
      if (hasAccumulation) flags.push("ACCUMULATION_PATTERN");
      flags.push("LINEAR_SCAN");

      return {
        notation: "O(n)",
        confidence: hasRecursion ? 75 : 90,
        flags
      };
    }

    // --- 8. CONSTANT (O(1)) ---
    // If no loops, no recursion, and no linear operations found
    return {
      notation: "O(1)",
      confidence: 95,
      flags
    };
  }

static calculateSpaceComplexity(
    loopDepth: number,
    allocationInLoop: number,
    hasRecursion: boolean,
    hasSorting: boolean,
    hasDeepClone: boolean,
    hasAccumulation: boolean
  ): CalculatorComplexityResult {
    const flags: string[] = [];

    // --- 1. QUADRATIC SPACE (O(n²)) ---
    // Deep cloning or Accumulation inside a loop creates a 2D data growth pattern
    if (loopDepth >= 1 && (hasDeepClone || hasAccumulation)) {
      flags.push("NESTED_ALLOCATION");
      return {
        notation: "O(n²)",
        confidence: 80,
        flags
      };
    }

    // --- 2. LINEAR SPACE (O(n)) ---
    // Recursion causes stack growth. Accumulation/Cloning causes heap growth.
    if (hasRecursion || hasAccumulation || hasDeepClone) {
      if (hasRecursion) flags.push("STACK_RECURSION");
      if (hasAccumulation) flags.push("HEAP_GROWTH");
      if (hasDeepClone) flags.push("OBJECT_CLONING");

      return {
        notation: "O(n)",
        // Recursion depth is an estimate, so lower confidence slightly
        confidence: hasRecursion ? 75 : 90,
        flags
      };
    }

    // --- 3. UNKNOWN / VOLATILE ---
    // If we see generic allocations in a loop but no specific pattern
    if (allocationInLoop > 0) {
      flags.push("LOOP_ALLOCATIONS");
      return {
        notation: "O(n^k)", // Mapping "Unknown" to "n^k" to match your allowed types
        confidence: 60,
        flags
      };
    }

    // --- 4. LOGARITHMIC SPACE (O(log n)) ---
    // Sorting (e.g., QuickSort) typically uses O(log n) stack space
    if (hasSorting) {
      flags.push("SORT_STACK_USAGE");
      return {
        notation: "O(log n)",
        confidence: 85,
        flags
      };
    }

    // --- 5. CONSTANT SPACE (O(1)) ---
    return {
      notation: "O(1)",
      confidence: 95,
      flags
    };
  }

static determineRiskLevel(totalScore: number): Uppercase_RiskLevelType {
    if (totalScore >= RISK_THRESHOLDS.CRITICAL) return "CRITICAL";
    if (totalScore >= RISK_THRESHOLDS.HIGH) return "HIGH";
    if (totalScore >= RISK_THRESHOLDS.MEDIUM) return "MEDIUM";
    return "LOW";
  }

static calculateOverallConfidence(signals: ASTSignals): number {
    let confidence = 100;

    if (signals.maxLoopDepth > 0) {
      confidence -= WEIGHTS.LOOP;
      confidence -= signals.maxLoopDepth * WEIGHTS.NESTED_LOOP_FACTOR;
    }

    if (signals.hasRecursion) {
      confidence -= signals.isBinaryRecursion
        ? WEIGHTS.BINARY_RECURSION
        : WEIGHTS.RECURSION;
    }

    if (signals.hasSorting) confidence -= WEIGHTS.SORT;
    if (signals.hasLinearSearch) confidence -= WEIGHTS.SEARCH_LINEAR;

    confidence -= signals.allocationsInLoop * WEIGHTS.ALLOCATION;

    if (signals.hasDeepClone) confidence -= WEIGHTS.DEEP_CLONE;
    if (signals.hasAccumulation) confidence -= WEIGHTS.ACCUMULATOR;

    confidence -= signals.matchedKeywords.length * WEIGHTS.KEYWORD_HIT;

    return Math.max(0, Math.min(100, Math.round(confidence)));
  }

static analyze(text: string, name: string, startLine: number): Partial<ComplexityResult> {
    const reasons: ComplexityReason[] = [];
    let timeScore = 0;
    let spaceScore = 0;

    // Count loops (traditional and functional)
    const loopMatches = text.match(/\b(for|while|do)\s*[\(\{]/g) || [];
    const forEachMatches = text.match(/\.(forEach|map|filter|reduce)\s*\(/g) || [];
    const totalLoops = loopMatches.length + forEachMatches.length;

    // IMPROVED: Better nesting detection - only count loop-related nesting
    const nestingDepth = this.estimateLoopNestingDepth(text);

    // Detect recursion
    const hasRecursion = name ? text.includes(`${name}(`) : false;

    // NEW: Try to detect binary recursion (multiple recursive calls)
    const recursionCallCount = name
      ? (text.match(new RegExp(`\\b${name}\\s*\\(`, 'g')) || []).length
      : 0;
    const likelyBinaryRecursion = recursionCallCount >= 2;

    // Detect sorting
    const hasSorting = /\.sort\s*\(/.test(text);

    // Detect expensive builtins
    const hasJSON = /JSON\.(parse|stringify)/.test(text);

    // NEW: Detect linear search methods
    const hasLinearSearch = /\.(includes|indexOf|find|findIndex)\s*\(/.test(text);

    // NEW: Critical pattern - linear search INSIDE loops (O(n²) killer!)
    const hasLinearSearchInLoop = totalLoops > 0 && hasLinearSearch;

    // NEW: Detect nested array methods (map inside map, etc)
    const hasNestedArrayMethods = /\.(map|filter|forEach|reduce)\s*\([^)]*\.(map|filter|includes|indexOf|find)/.test(text);

    // Detect allocations
    const allocationMatches = text.match(/new\s+(Array|Object|Map|Set)|\.push\s*\(|\.concat\s*\(/g) || [];
    const spreadMatches = text.match(/\.\.\.|spread/g) || [];

    // ===================
    // TIME COMPLEXITY
    // ===================

    // Pattern 1: Nested loops (most critical for time)
    // 1. Loop structure scoring
    if (nestingDepth > 1) {
      const nestedLoopScore =
        Math.pow(nestingDepth, 2) * WEIGHTS.NESTED_LOOP_FACTOR;

      timeScore += nestedLoopScore;

      reasons.push(
        FreeTierReasonGenerator.generateTimeReason(
          `nested-loop-${Math.min(nestingDepth, 3)}`,
          {
            loopDepth: nestingDepth,
            lineNumber: startLine,
          }
        )
      );
    } else if (totalLoops > 0) {
      // Multiple independent loops → O(k·n)
      timeScore += totalLoops * WEIGHTS.LOOP;

      const pattern =
        totalLoops === 1
          ? "single-loop"
          : totalLoops <= 3
            ? "many-loops"
            : "excessive-loops";

      reasons.push(
        FreeTierReasonGenerator.generateTimeReason(pattern, {
          loopDepth: totalLoops,
          lineNumber: startLine,
        })
      );
    }

    // Pattern 2: Linear search in loops (hidden O(n²))
    if (hasLinearSearchInLoop) {
      timeScore += WEIGHTS.NESTED_LOOP_FACTOR * 1.5; // High penalty
      reasons.push(FreeTierReasonGenerator.generateTimeReason("loop-with-includes", {
        lineNumber: startLine,
        searchMethod: hasLinearSearch
      }));
    }

    // Pattern 3: Nested array methods
    if (hasNestedArrayMethods) {
      timeScore += WEIGHTS.NESTED_LOOP_FACTOR;
      reasons.push(FreeTierReasonGenerator.generateTimeReason("nested-array-methods", {
        lineNumber: startLine
      }));
    }

    // Pattern 4: Recursion
    if (hasRecursion) {
      if (likelyBinaryRecursion) {
        timeScore += WEIGHTS.RECURSION * 3; // Higher penalty for exponential
        reasons.push(FreeTierReasonGenerator.generateTimeReason("recursion-binary", {
          isRecursive: true,
          callName: name,
          callCount: recursionCallCount,
          lineNumber: startLine
        }));
      } else {
        timeScore += WEIGHTS.RECURSION;
        reasons.push(FreeTierReasonGenerator.generateTimeReason("recursion-simple", {
          isRecursive: true,
          callName: name,
          lineNumber: startLine
        }));
      }
    }

    // Pattern 5: Sorting
    if (hasSorting) {
      timeScore += WEIGHTS.SORT;
      reasons.push(FreeTierReasonGenerator.generateTimeReason("sort", {
        lineNumber: startLine
      }));
    }

    // Pattern 6: JSON operations
    if (hasJSON) {
      timeScore += WEIGHTS.HIGH_COST_BUILTIN;
      reasons.push(FreeTierReasonGenerator.generateTimeReason("json-operations", {
        lineNumber: startLine
      }));
    }

    // Pattern 7: Simple linear search (without loop)
    if (hasLinearSearch && !hasLinearSearchInLoop && totalLoops === 0) {
      reasons.push(FreeTierReasonGenerator.generateTimeReason("includes-indexof", {
        lineNumber: startLine
      }));
    }

    // ===================
    // SPACE COMPLEXITY
    // ===================

    // Pattern 1: Allocations in loops
    if (allocationMatches.length > 0 && totalLoops > 0) {
      spaceScore += allocationMatches.length * WEIGHTS.PUSH_IN_LOOP;
      reasons.push(FreeTierReasonGenerator.generateSpaceReason("array-allocation-loop", {
        inLoop: true,
        allocationType: "array/object",
        lineNumber: startLine,
        growthPattern: nestingDepth >= 2 ? "quadratic" : "linear"
      }));
    }

    // Pattern 2: Spread operator
    if (spreadMatches.length > 0) {
      const spreadPenalty = totalLoops > 0
        ? spreadMatches.length * WEIGHTS.SPREAD * 2  // Higher penalty in loops
        : spreadMatches.length * WEIGHTS.SPREAD;

      spaceScore += spreadPenalty;
      reasons.push(FreeTierReasonGenerator.generateSpaceReason("spread-operator", {
        inLoop: totalLoops > 0,
        lineNumber: startLine
      }));
    }

    // Pattern 3: Recursion stack space
    if (hasRecursion) {
      spaceScore += WEIGHTS.RECURSION_SPACE;
    }

    // Pattern 4: JSON creates full copy
    if (hasJSON) {
      spaceScore += WEIGHTS.HIGH_COST_BUILTIN * 0.5; // JSON uses O(n) space
    }

    // Calculate final complexities
    const timeComplexity = FreeTierComplexityCalculator.calculateTimeComplexity(
      nestingDepth,
      hasRecursion,
      likelyBinaryRecursion,
      hasSorting,
      hasLinearSearchInLoop || hasNestedArrayMethods
    );

    const spaceComplexity = FreeTierComplexityCalculator.calculateSpaceComplexity(
      allocationMatches.length,
      hasRecursion,
      nestingDepth,
      hasJSON,
      allocationMatches.length > 0 && totalLoops > 0
    );

    const totalScore = timeScore + spaceScore;
    const riskLevel = FreeTierComplexityCalculator.determineRiskLevel(totalScore);

    // REDUCED confidence for free tier since it's regex-based estimates
    const baseConfidence = FreeTierComplexityCalculator.calculateOverallConfidence(reasons);
    const confidence = Math.min(baseConfidence * 0.75, 0.70); // Cap at 70% for free tier

    return {
      timeComplexity,
      spaceComplexity,
      timeScore,
      spaceScore,
      totalScore,
      riskLevel,
      reasons,
      confidence,
      tierUsed: "free"
    };
  }

private static estimateLoopNestingDepth(text: string): number {
    let maxDepth = 0;
    let currentDepth = 0;
    const blockStack: boolean[] = [];

    const lines = text.split('\n');

    for (let line of lines) {
      // Remove strings and comments (basic heuristic)
      line = line.replace(/\/\/.*$/g, ''); // remove single-line comments
      line = line.replace(/\/\*.*\*\//g, ''); // remove block comments
      line = line.replace(/(["'`]).*?\1/g, ''); // remove string literals

      // Count all loop keywords in the line
      const loopKeywords = line.match(/\b(for|while|do|forEach|map|filter|reduce)\b/g) || [];
      const openBraces = (line.match(/\{/g) || []).length;
      const closeBraces = (line.match(/\}/g) || []).length;

      // Handle loop keywords
      for (let i = 0; i < loopKeywords.length; i++) {
        // If brace exists, push as loop block
        if (openBraces > i) {
          blockStack.push(true);
        } else {
          // No brace, assume next line is loop block, mark as "virtual" loop
          blockStack.push(true);
        }
        currentDepth++;
        maxDepth = Math.max(maxDepth, currentDepth);
      }

      // Track non-loop blocks for extra braces
      const nonLoopBlocks = Math.max(0, openBraces - loopKeywords.length);
      for (let i = 0; i < nonLoopBlocks; i++) {
        blockStack.push(false);
      }

      // Close blocks
      for (let i = 0; i < closeBraces; i++) {
        const isLoopBlock = blockStack.pop();
        if (isLoopBlock) {
          currentDepth = Math.max(0, currentDepth - 1);
        }
      }
    }

    return maxDepth;
  }

static generateTimeReason(
    pattern: string,
    context: {
      loopDepth?: number;
      callName?: string;
      lineNumber?: number;
      isRecursive?: boolean;
      nestedWith?: string;
      callCount?: number;        // NEW: For binary recursion detection
      searchMethod?: boolean;    // NEW: For linear search detection
    }
  ): ComplexityReason {
    const complexityPattern = COMPLEXITY_PATTERNS_FREE[pattern];

    if (!complexityPattern) {
      return {
        type: "unknown",
        pattern,
        detail: `We detected a '${pattern}' construct, but it does not match any known complexity pattern. Manual review is recommended.`,
        impact: "unknown",
        confidence: 10,
        lineNumber: context.lineNumber
      };
    }


    let detail = complexityPattern.reason;
    let confidence = 70;
    let impact: ComplexityReason["impact"] = "medium";
    // Context 1: Single loop

    const loopDepth = context.loopDepth;

    if (typeof loopDepth === "number") {
      confidence = 85;

      const impactByDepth: Record<number, ComplexityReason["impact"]> = {
        1: "low",
        2: "medium",
        3: "high",
      };

      impact = impactByDepth[loopDepth] ?? "critical";
    }

    // Context 2: Binary recursion (exponential growth)
    if (context.isRecursive && context.callCount && context.callCount >= 2) {
      confidence = 75; // Lower confidence since regex can't be 100% sure
      impact = "critical";
    }
    // Context 2b: Simple recursion (linear)
    else if (context.isRecursive && context.callName) {
      confidence = 80;
      impact = "medium";
    }

    // Context 3: Linear search in loops (hidden O(n²))
    if (context.searchMethod) {
      confidence = 85;
      impact = "high";
    }

    // Context 4: Method name context
    if (context.callName && !context.isRecursive && !context.searchMethod) {
      confidence = 80;
    }

    // Context 5: Nested with another operation
    if (context.nestedWith) {
      impact = "high";
      confidence = 90;
    }

    return {
      type: "time",
      pattern,
      detail,
      impact,
      confidence,
      lineNumber: context.lineNumber
    };
  }

static generateSpaceReason(
    pattern: string,
    context: {
      allocationType?: string;
      inLoop?: boolean;
      lineNumber?: number;
      growthPattern?: string;
    }
  ): ComplexityReason {
    const complexityPattern = COMPLEXITY_PATTERNS_FREE[pattern];

    if (!complexityPattern) {
      return {
        type: "unknown",
        pattern,
        detail: `We detected a '${pattern}' construct, but it does not match any known complexity pattern. Manual review is recommended.`,
        impact: "unknown",
        confidence: 10,
        lineNumber: context.lineNumber
      };
    }

    let detail = complexityPattern.reason
    let confidence = 65;
    let impact: ComplexityReason["impact"] = "medium";

    if (context.inLoop) {
      confidence = 85;
      impact = "high";
