(n: Node, insideLoop: boolean, insideRecursion: boolean): void => {

      const kind = n.getKind();

      // ── LOOP detection ─────────────────────────────────────────────────
      if (LOOP_KINDS.has(kind)) {
        loops++;
        currentLoopDepth++;
        maxLoopDepth = Math.max(maxLoopDepth, currentLoopDepth);
        insideLoop = true;

