    getComplexityGenerator: GetComplexityGenerator
  ) {
    this.getUnitPartOfCode = getUnitPartOfCode;
    this.getIfCodeChange = getIfCodeChange;
    this.cancelRunningTask = cancelRunningTask;
    this.getComplexityGenerator = getComplexityGenerator;
  }

constructor(keywordSet: Set<string>, enhancedAnalyzer: EnhancedAnalyzer_v2) {
    this.keywordSet = keywordSet;
    this.enhancedAnalyzer = enhancedAnalyzer
  }

export function createCompiler() {
  const aiComplexityExplainer = new ComplexityReasonGenerator();
  const enhancedAnalyzer = new EnhancedAnalyzer_v2(aiComplexityExplainer)
  const complexityEngineGenerator = new ComplexityOrchestrator_v1(BuildKeywordSet, enhancedAnalyzer)



  return new Compiler(
    new GetUnitPartOfCode(),
    new GetCodeChanges(),
    new CancelRunningTask(),
    new GetComplexityGenerator(complexityEngineGenerator)
  );
}

