static calculateTimeComplexity(
    loopDepth: number,
    hasRecursion: boolean,
    isBinaryRecursion: boolean,
    hasSorting: boolean,
    hasLinearSearch: boolean,
    hasDeepClone: boolean,
    hasAccumulation: boolean
  ): CalculatorComplexityResult {
    const flags: string[] = [];

    // --- 1. FACTORIAL GROWTH (O(n!)) ---
    // Recursion combined with loops or permutations
    if (hasRecursion && loopDepth >= 1 && (hasSorting || isBinaryRecursion)) {
      flags.push("FACTORIAL_EXPLOSION");
      return { notation: "O(n!)", confidence: 70, flags };
    }

    // --- 2. EXPONENTIAL GROWTH (O(2^n)) ---
    if (isBinaryRecursion || (hasRecursion && hasDeepClone)) {
      flags.push("EXPONENTIAL_RECURSION");
      return { notation: "O(2^n)", confidence: 85, flags };
    }

    // --- 3. UNKNOWN HIGH POLYNOMIAL (O(n^k)) ---
    // Depth 4+ is usually the threshold where we stop precise naming
    if (loopDepth >= 4) {
      flags.push("DEEP_NESTING_EXCESSIVE");
      return { notation: "O(n^k)", confidence: 90, flags };
    }

    // --- 4. CUBIC GROWTH (O(n³)) ---
    // Depth 3, or Depth 2 with heavy operations like sorting
    if (loopDepth === 3 || (loopDepth === 2 && hasSorting)) {
      flags.push("CUBIC_COMPLEXITY");
      return { notation: "O(n³)", confidence: 80, flags };
    }

    // --- 5. QUADRATIC GROWTH (O(n²)) ---
    // Depth 2, or Depth 1 with Linear Search/Sorting/Deep Clone
    if (loopDepth === 2) {
      flags.push("NESTED_LOOPS");
      return { notation: "O(n²)", confidence: 95, flags };
    }

    if (loopDepth === 1 && (hasLinearSearch || hasSorting || hasDeepClone)) {
      flags.push("SEARCH_OR_SORT_IN_LOOP");
      // O(n * log n) or O(n * n) both map here for safety
      return { notation: "O(n²)", confidence: 85, flags };
    }

    // --- 6. SUPERLINEAR (O(n log n)) ---
    if (hasSorting) {
      flags.push("SORTING_ALGORITHM");
      return { notation: "O(n log n)", confidence: 95, flags };
    }

    // --- 7. LINEAR (O(n)) ---
    if (loopDepth === 1 || hasLinearSearch || hasRecursion || hasAccumulation) {
      if (hasRecursion) flags.push("RECURSIVE_WALK");
      if (hasAccumulation) flags.push("ACCUMULATION_PATTERN");
      flags.push("LINEAR_SCAN");

      return {
        notation: "O(n)",
        confidence: hasRecursion ? 75 : 90,
        flags
      };
    }

    // --- 8. CONSTANT (O(1)) ---
    // If no loops, no recursion, and no linear operations found
    return {
      notation: "O(1)",
      confidence: 95,
      flags
    };
  }

static calculateSpaceComplexity(
    loopDepth: number,
    allocationInLoop: number,
    hasRecursion: boolean,
    hasSorting: boolean,
    hasDeepClone: boolean,
    hasAccumulation: boolean
  ): CalculatorComplexityResult {
    const flags: string[] = [];

    // --- 1. QUADRATIC SPACE (O(n²)) ---
    // Deep cloning or Accumulation inside a loop creates a 2D data growth pattern
    if (loopDepth >= 1 && (hasDeepClone || hasAccumulation)) {
      flags.push("NESTED_ALLOCATION");
      return {
        notation: "O(n²)",
        confidence: 80,
        flags
      };
    }

    // --- 2. LINEAR SPACE (O(n)) ---
    // Recursion causes stack growth. Accumulation/Cloning causes heap growth.
    if (hasRecursion || hasAccumulation || hasDeepClone) {
      if (hasRecursion) flags.push("STACK_RECURSION");
      if (hasAccumulation) flags.push("HEAP_GROWTH");
      if (hasDeepClone) flags.push("OBJECT_CLONING");

      return {
        notation: "O(n)",
        // Recursion depth is an estimate, so lower confidence slightly
        confidence: hasRecursion ? 75 : 90,
        flags
      };
    }

    // --- 3. UNKNOWN / VOLATILE ---
    // If we see generic allocations in a loop but no specific pattern
    if (allocationInLoop > 0) {
      flags.push("LOOP_ALLOCATIONS");
      return {
        notation: "O(n^k)", // Mapping "Unknown" to "n^k" to match your allowed types
        confidence: 60,
        flags
      };
    }

    // --- 4. LOGARITHMIC SPACE (O(log n)) ---
    // Sorting (e.g., QuickSort) typically uses O(log n) stack space
    if (hasSorting) {
      flags.push("SORT_STACK_USAGE");
      return {
        notation: "O(log n)",
        confidence: 85,
        flags
      };
    }

    // --- 5. CONSTANT SPACE (O(1)) ---
    return {
      notation: "O(1)",
      confidence: 95,
      flags
    };
  }

static determineRiskLevel(totalScore: number): Uppercase_RiskLevelType {
    if (totalScore >= RISK_THRESHOLDS.CRITICAL) return "CRITICAL";
    if (totalScore >= RISK_THRESHOLDS.HIGH) return "HIGH";
    if (totalScore >= RISK_THRESHOLDS.MEDIUM) return "MEDIUM";
    return "LOW";
  }

static calculateOverallConfidence(signals: ASTSignals): number {
    let confidence = 100;

    if (signals.maxLoopDepth > 0) {
      confidence -= WEIGHTS.LOOP;
      confidence -= signals.maxLoopDepth * WEIGHTS.NESTED_LOOP_FACTOR;
    }

    if (signals.hasRecursion) {
      confidence -= signals.isBinaryRecursion
        ? WEIGHTS.BINARY_RECURSION
        : WEIGHTS.RECURSION;
    }

    if (signals.hasSorting) confidence -= WEIGHTS.SORT;
    if (signals.hasLinearSearch) confidence -= WEIGHTS.SEARCH_LINEAR;

    confidence -= signals.allocationsInLoop * WEIGHTS.ALLOCATION;

    if (signals.hasDeepClone) confidence -= WEIGHTS.DEEP_CLONE;
    if (signals.hasAccumulation) confidence -= WEIGHTS.ACCUMULATOR;

    confidence -= signals.matchedKeywords.length * WEIGHTS.KEYWORD_HIT;

    return Math.max(0, Math.min(100, Math.round(confidence)));
  }

static analyze(text: string, name: string, startLine: number): Partial<ComplexityResult> {
    const reasons: ComplexityReason[] = [];
    let timeScore = 0;
    let spaceScore = 0;

    // Count loops (traditional and functional)
    const loopMatches = text.match(/\b(for|while|do)\s*[\(\{]/g) || [];
    const forEachMatches = text.match(/\.(forEach|map|filter|reduce)\s*\(/g) || [];
    const totalLoops = loopMatches.length + forEachMatches.length;

    // IMPROVED: Better nesting detection - only count loop-related nesting
    const nestingDepth = this.estimateLoopNestingDepth(text);

    // Detect recursion
    const hasRecursion = name ? text.includes(`${name}(`) : false;

    // NEW: Try to detect binary recursion (multiple recursive calls)
    const recursionCallCount = name
      ? (text.match(new RegExp(`\\b${name}\\s*\\(`, 'g')) || []).length
      : 0;
    const likelyBinaryRecursion = recursionCallCount >= 2;

    // Detect sorting
    const hasSorting = /\.sort\s*\(/.test(text);

    // Detect expensive builtins
    const hasJSON = /JSON\.(parse|stringify)/.test(text);

    // NEW: Detect linear search methods
    const hasLinearSearch = /\.(includes|indexOf|find|findIndex)\s*\(/.test(text);

    // NEW: Critical pattern - linear search INSIDE loops (O(n²) killer!)
    const hasLinearSearchInLoop = totalLoops > 0 && hasLinearSearch;

    // NEW: Detect nested array methods (map inside map, etc)
    const hasNestedArrayMethods = /\.(map|filter|forEach|reduce)\s*\([^)]*\.(map|filter|includes|indexOf|find)/.test(text);

    // Detect allocations
    const allocationMatches = text.match(/new\s+(Array|Object|Map|Set)|\.push\s*\(|\.concat\s*\(/g) || [];
    const spreadMatches = text.match(/\.\.\.|spread/g) || [];

    // ===================
    // TIME COMPLEXITY
    // ===================

    // Pattern 1: Nested loops (most critical for time)
    // 1. Loop structure scoring
    if (nestingDepth > 1) {
      const nestedLoopScore =
        Math.pow(nestingDepth, 2) * WEIGHTS.NESTED_LOOP_FACTOR;

      timeScore += nestedLoopScore;

      reasons.push(
        FreeTierReasonGenerator.generateTimeReason(
          `nested-loop-${Math.min(nestingDepth, 3)}`,
          {
            loopDepth: nestingDepth,
            lineNumber: startLine,
          }
        )
      );
    } else if (totalLoops > 0) {
      // Multiple independent loops → O(k·n)
      timeScore += totalLoops * WEIGHTS.LOOP;

      const pattern =
        totalLoops === 1
          ? "single-loop"
          : totalLoops <= 3
            ? "many-loops"
            : "excessive-loops";

      reasons.push(
        FreeTierReasonGenerator.generateTimeReason(pattern, {
          loopDepth: totalLoops,
          lineNumber: startLine,
        })
      );
    }

    // Pattern 2: Linear search in loops (hidden O(n²))
    if (hasLinearSearchInLoop) {
      timeScore += WEIGHTS.NESTED_LOOP_FACTOR * 1.5; // High penalty
      reasons.push(FreeTierReasonGenerator.generateTimeReason("loop-with-includes", {
        lineNumber: startLine,
        searchMethod: hasLinearSearch
      }));
    }

    // Pattern 3: Nested array methods
    if (hasNestedArrayMethods) {
      timeScore += WEIGHTS.NESTED_LOOP_FACTOR;
      reasons.push(FreeTierReasonGenerator.generateTimeReason("nested-array-methods", {
        lineNumber: startLine
      }));
    }

    // Pattern 4: Recursion
    if (hasRecursion) {
      if (likelyBinaryRecursion) {
        timeScore += WEIGHTS.RECURSION * 3; // Higher penalty for exponential
        reasons.push(FreeTierReasonGenerator.generateTimeReason("recursion-binary", {
          isRecursive: true,
          callName: name,
          callCount: recursionCallCount,
          lineNumber: startLine
        }));
      } else {
        timeScore += WEIGHTS.RECURSION;
        reasons.push(FreeTierReasonGenerator.generateTimeReason("recursion-simple", {
          isRecursive: true,
          callName: name,
          lineNumber: startLine
        }));
      }
    }

    // Pattern 5: Sorting
    if (hasSorting) {
      timeScore += WEIGHTS.SORT;
      reasons.push(FreeTierReasonGenerator.generateTimeReason("sort", {
        lineNumber: startLine
      }));
    }

    // Pattern 6: JSON operations
    if (hasJSON) {
      timeScore += WEIGHTS.HIGH_COST_BUILTIN;
      reasons.push(FreeTierReasonGenerator.generateTimeReason("json-operations", {
        lineNumber: startLine
      }));
    }

    // Pattern 7: Simple linear search (without loop)
    if (hasLinearSearch && !hasLinearSearchInLoop && totalLoops === 0) {
      reasons.push(FreeTierReasonGenerator.generateTimeReason("includes-indexof", {
        lineNumber: startLine
      }));
    }

    // ===================
    // SPACE COMPLEXITY
    // ===================

    // Pattern 1: Allocations in loops
    if (allocationMatches.length > 0 && totalLoops > 0) {
      spaceScore += allocationMatches.length * WEIGHTS.PUSH_IN_LOOP;
      reasons.push(FreeTierReasonGenerator.generateSpaceReason("array-allocation-loop", {
        inLoop: true,
        allocationType: "array/object",
        lineNumber: startLine,
        growthPattern: nestingDepth >= 2 ? "quadratic" : "linear"
      }));
    }

    // Pattern 2: Spread operator
    if (spreadMatches.length > 0) {
      const spreadPenalty = totalLoops > 0
        ? spreadMatches.length * WEIGHTS.SPREAD * 2  // Higher penalty in loops
        : spreadMatches.length * WEIGHTS.SPREAD;

      spaceScore += spreadPenalty;
      reasons.push(FreeTierReasonGenerator.generateSpaceReason("spread-operator", {
        inLoop: totalLoops > 0,
        lineNumber: startLine
      }));
    }

    // Pattern 3: Recursion stack space
    if (hasRecursion) {
      spaceScore += WEIGHTS.RECURSION_SPACE;
    }

    // Pattern 4: JSON creates full copy
    if (hasJSON) {
      spaceScore += WEIGHTS.HIGH_COST_BUILTIN * 0.5; // JSON uses O(n) space
    }

    // Calculate final complexities
    const timeComplexity = FreeTierComplexityCalculator.calculateTimeComplexity(
      nestingDepth,
      hasRecursion,
      likelyBinaryRecursion,
      hasSorting,
      hasLinearSearchInLoop || hasNestedArrayMethods
    );

    const spaceComplexity = FreeTierComplexityCalculator.calculateSpaceComplexity(
      allocationMatches.length,
      hasRecursion,
      nestingDepth,
      hasJSON,
      allocationMatches.length > 0 && totalLoops > 0
    );

    const totalScore = timeScore + spaceScore;
    const riskLevel = FreeTierComplexityCalculator.determineRiskLevel(totalScore);

    // REDUCED confidence for free tier since it's regex-based estimates
    const baseConfidence = FreeTierComplexityCalculator.calculateOverallConfidence(reasons);
    const confidence = Math.min(baseConfidence * 0.75, 0.70); // Cap at 70% for free tier

    return {
      timeComplexity,
      spaceComplexity,
      timeScore,
      spaceScore,
      totalScore,
      riskLevel,
      reasons,
      confidence,
      tierUsed: "free"
    };
  }

private static estimateLoopNestingDepth(text: string): number {
    let maxDepth = 0;
    let currentDepth = 0;
    const blockStack: boolean[] = [];

    const lines = text.split('\n');

    for (let line of lines) {
      // Remove strings and comments (basic heuristic)
      line = line.replace(/\/\/.*$/g, ''); // remove single-line comments
      line = line.replace(/\/\*.*\*\//g, ''); // remove block comments
      line = line.replace(/(["'`]).*?\1/g, ''); // remove string literals

      // Count all loop keywords in the line
      const loopKeywords = line.match(/\b(for|while|do|forEach|map|filter|reduce)\b/g) || [];
      const openBraces = (line.match(/\{/g) || []).length;
      const closeBraces = (line.match(/\}/g) || []).length;

      // Handle loop keywords
      for (let i = 0; i < loopKeywords.length; i++) {
        // If brace exists, push as loop block
        if (openBraces > i) {
          blockStack.push(true);
        } else {
          // No brace, assume next line is loop block, mark as "virtual" loop
          blockStack.push(true);
        }
        currentDepth++;
        maxDepth = Math.max(maxDepth, currentDepth);
      }

      // Track non-loop blocks for extra braces
      const nonLoopBlocks = Math.max(0, openBraces - loopKeywords.length);
      for (let i = 0; i < nonLoopBlocks; i++) {
        blockStack.push(false);
      }

      // Close blocks
      for (let i = 0; i < closeBraces; i++) {
        const isLoopBlock = blockStack.pop();
        if (isLoopBlock) {
          currentDepth = Math.max(0, currentDepth - 1);
        }
      }
    }

    return maxDepth;
  }

static generateTimeReason(
    pattern: string,
    context: {
      loopDepth?: number;
      callName?: string;
      lineNumber?: number;
      isRecursive?: boolean;
      nestedWith?: string;
      callCount?: number;        // NEW: For binary recursion detection
      searchMethod?: boolean;    // NEW: For linear search detection
    }
  ): ComplexityReason {
    const complexityPattern = COMPLEXITY_PATTERNS_FREE[pattern];

    if (!complexityPattern) {
      return {
        type: "unknown",
        pattern,
        detail: `We detected a '${pattern}' construct, but it does not match any known complexity pattern. Manual review is recommended.`,
        impact: "unknown",
        confidence: 10,
        lineNumber: context.lineNumber
      };
    }


    let detail = complexityPattern.reason;
    let confidence = 70;
    let impact: ComplexityReason["impact"] = "medium";
    // Context 1: Single loop

    const loopDepth = context.loopDepth;

    if (typeof loopDepth === "number") {
      confidence = 85;

      const impactByDepth: Record<number, ComplexityReason["impact"]> = {
        1: "low",
        2: "medium",
        3: "high",
      };

      impact = impactByDepth[loopDepth] ?? "critical";
    }

    // Context 2: Binary recursion (exponential growth)
    if (context.isRecursive && context.callCount && context.callCount >= 2) {
      confidence = 75; // Lower confidence since regex can't be 100% sure
      impact = "critical";
    }
    // Context 2b: Simple recursion (linear)
    else if (context.isRecursive && context.callName) {
      confidence = 80;
      impact = "medium";
    }

    // Context 3: Linear search in loops (hidden O(n²))
    if (context.searchMethod) {
      confidence = 85;
      impact = "high";
    }

    // Context 4: Method name context
    if (context.callName && !context.isRecursive && !context.searchMethod) {
      confidence = 80;
    }

    // Context 5: Nested with another operation
    if (context.nestedWith) {
      impact = "high";
      confidence = 90;
    }

    return {
      type: "time",
      pattern,
      detail,
      impact,
      confidence,
      lineNumber: context.lineNumber
    };
  }

static generateSpaceReason(
    pattern: string,
    context: {
      allocationType?: string;
      inLoop?: boolean;
      lineNumber?: number;
      growthPattern?: string;
    }
  ): ComplexityReason {
    const complexityPattern = COMPLEXITY_PATTERNS_FREE[pattern];

    if (!complexityPattern) {
      return {
        type: "unknown",
        pattern,
        detail: `We detected a '${pattern}' construct, but it does not match any known complexity pattern. Manual review is recommended.`,
        impact: "unknown",
        confidence: 10,
        lineNumber: context.lineNumber
      };
    }

    let detail = complexityPattern.reason
    let confidence = 65;
    let impact: ComplexityReason["impact"] = "medium";

    if (context.inLoop) {
      confidence = 85;
      impact = "high";
    }

    if (context.allocationType) {
      confidence = 75;
    }

    if (context.growthPattern === "linear") {
      impact = "medium";
    } else if (context.growthPattern === "quadratic") {
      impact = "critical";
    }

    return {
      type: "space",
      pattern,
      detail,
      impact,
      confidence,
      lineNumber: context.lineNumber
    };
  }

public async executePaidTier(fetchPartOfCodeResult: normalizedPayloadData): Promise<AnalysisSummary> {
    return this.analyzeDeep(fetchPartOfCodeResult);
  }

public async executeFreeTier(fetchPartOfCodeResult: normalizedPayloadData): Promise<AnalysisSummary> {
    return this.analyzeFast(fetchPartOfCodeResult);
  }

private async analyzeFast(
    fetchPartOfCodeResult: normalizedPayloadData
  ): Promise<AnalysisSummary> {
    const resultsByUnit = await this.processUnits(
      fetchPartOfCodeResult,
      async (node, unitType, idx) => await this.analyzeFastNode(node, unitType, `${unitType}_${idx}`)
    );

    return this.buildSummary(
      fetchPartOfCodeResult.nameOfFile,
      resultsByUnit,
      "free"
    );
  }

private async analyzeDeep(
    fetchPartOfCodeResult: normalizedPayloadData
  ): Promise<AnalysisSummary> {
    const resultsByUnit = await this.processUnits(
      fetchPartOfCodeResult,
      async (node, unitType, idx) => await this.analyzeDeepNode(node, unitType, `${unitType}_${idx}`)
    );

    return this.buildSummary(
      fetchPartOfCodeResult.nameOfFile,
      resultsByUnit,
      "paid"
    );
  }

private async analyzeFastNode(
    node: any,
    kind: fetchUnitPartOfCodeArrayTargets,
    nameHint?: string
  ): Promise<ComplexityResult> {
    const name = this.extractNodeName(node, nameHint);
    const startLine = this.getStartLine(node);
    const endLine = this.getEndLine(node);
    const text = this.extractNodeText(node);

    const fastResult = await FastAnalyzer.analyze(text, name || "", startLine);
    const matchedKeywords = await this.findKeywordMatches(text);

    return {
      id: `${name || "anon"}:${startLine}`,
      kind,
      name,
      startLine,
      endLine,
      text,
      timeComplexity: fastResult.timeComplexity!,
      spaceComplexity: fastResult.spaceComplexity!,
      timeScore: fastResult.timeScore!,
      spaceScore: fastResult.spaceScore!,
      totalScore: fastResult.totalScore!,
      riskLevel: fastResult.riskLevel!,
      confidence: fastResult.confidence!,
      reasons: fastResult.reasons!,
      matchedKeywords,
      tierUsed: "free"
    };
  }

private async analyzeDeepNode(
    node: Node,
    kind: fetchUnitPartOfCodeArrayTargets,
    nameHint?: string,
  ): Promise<ComplexityResult> {
    const name = this.extractNodeName(node, nameHint);
    const startLine = this.getStartLine(node);
    const endLine = this.getEndLine(node);
    const text = this.extractNodeText(node);

    const reasons: PaidComplexityReason[] = [];



    /*//////////////////////////////////////////////////////////////
                          NEW VERSION IMPLEMENTATION
        //////////////////////////////////////////////////////////////*/


    const { success, result: newComplexityEnhancer } = this.enhancedAnalyzer.run(node, name, this.keywordSet)
    if (!success || newComplexityEnhancer == undefined) {
      throw new Error("Paid complexity failed to run")
    }

    const resultFormat = {
      id: `${name || "anon"}:${startLine}`,
      kind,
      name,
      startLine,
      endLine,
      text,
      timeComplexity: newComplexityEnhancer.timeComplexity,
      spaceComplexity: newComplexityEnhancer.spaceComplexity,
      timeScore: Math.round(newComplexityEnhancer.timeScore),
      spaceScore: Math.round(newComplexityEnhancer.spaceScore),
      totalScore: newComplexityEnhancer.totalScore,
      riskLevel: newComplexityEnhancer.riskLevel,
      confidence: newComplexityEnhancer.confidence,
      reasons,
      matchedKeywords: ["No key word added for now"],
      tierUsed: "paid"
    };

    // temprarily store result
    await tempManualStorage(resultFormat, "paid-complexity-result.json")


    return {
      id: `${name || "anon"}:${startLine}`,
      kind,
      name,
      startLine,
      endLine,
      text,
      timeComplexity: newComplexityEnhancer.timeComplexity,
      spaceComplexity: newComplexityEnhancer.spaceComplexity,
      timeScore: Math.round(newComplexityEnhancer.timeScore),
      spaceScore: Math.round(newComplexityEnhancer.spaceScore),
      totalScore: newComplexityEnhancer.totalScore,
      riskLevel: newComplexityEnhancer.riskLevel,
      confidence: newComplexityEnhancer.confidence,
      reasons,
      matchedKeywords: ["No key word added for now"],
      tierUsed: "paid"
    }
  }

private async processUnits(
    fetchPartOfCodeResult: normalizedPayloadData,
    analyzeNode: (node: any, unitType: UnitTarget, idx: number) => Promise<ComplexityResult>
  ): Promise<Record<UnitTarget, any[]>> {
    const resultsByUnit: Record<UnitTarget, any[]> = {} as any;

    for (const [unitType, nodes] of Object.entries(fetchPartOfCodeResult)) {
      if (unitType === "nameOfFile") continue;

      const typedUnit = unitType as UnitTarget;
      resultsByUnit[typedUnit] = await Promise.all(
        this.ensureArray(nodes).map((node, idx) =>
          analyzeNode(node, typedUnit, idx)
        )
      );

    }

    return resultsByUnit;
  }

private extractNodeName(node: any, nameHint?: string): string | null {
    return nameHint || (node.getName ? node.getName() : null);
  }

private extractNodeText(node: any): string {
    return node.getText ? node.getText() : (node.text || "");
  }

private getStartLine(node: Node): number {
    try {
      return (node as any).getStartLineNumber ? (node as any).getStartLineNumber() : 0;
    } catch {
      return 0;
    }
  }

private getEndLine(node: Node): number {
    try {
      return (node as any).getEndLineNumber ? (node as any).getEndLineNumber() : 0;
    } catch {
      return 0;
    }
  }

private ensureArray(x: any): any[] {
    if (!x) return [];
    if (Array.isArray(x)) return x;
    return [x];
  }

private findKeywordMatches(text: string): string[] {
    const tokens = text.split(/[^A-Za-z0-9_$\.]+/).filter(Boolean);
    return tokens.filter(t => this.keywordSet.has(t));
  }

private buildSummary(
    fileName: string,
    allCodeUnitResult: Record<UnitTarget, any[]>,
    tier: TierLevel
  ): AnalysisSummary {
    const all = Object.values(allCodeUnitResult).flat();

    const totalScore = all.reduce((s, it) => s + it.totalScore, 0);
    const avgScore = all.length ? Math.round(totalScore / all.length) : 0;

    const criticalRisk = all.filter(a => a.riskLevel === "CRITICAL");
    const highRisk = all.filter(a => a.riskLevel === "HIGH");
    const mediumRisk = all.filter(a => a.riskLevel === "MEDIUM");

    const avgTimeComplexity = this.calculateAverageComplexity(
      all.map(a => a.timeComplexity)
    );

    const avgSpaceComplexity = this.calculateAverageComplexity(
      all.map(a => a.spaceComplexity)
    );

    return {
      nameOfFile: fileName,
      success: true,
      generatedAt: new Date().toISOString(),
      tierUsed: tier,
      summary: {
        itemsAnalyzed: all.length,
        totalScore,
        avgScore,
        avgTimeComplexity,
        avgSpaceComplexity,
        criticalRiskCount: criticalRisk.length,
        highRiskCount: highRisk.length,
        mediumRiskCount: mediumRisk.length,
        lowRiskCount:
          all.length -
          criticalRisk.length -
          highRisk.length -
          mediumRisk.length
      },
      details: allCodeUnitResult
    };
  }

private calculateAverageComplexity(complexities: ComplexityNotation[]): string {
    if (complexities.length === 0) return "O(1).js";

    const complexityOrder: ComplexityNotation[] = [
      "O(1)", "O(log n)", "O(n)", "O(n log n)", "O(n^k)", "O(2^n)", "UNKNOWN"
    ];

    let maxIndex = 0;
    for (const c of complexities) {
      const index = complexityOrder.indexOf(c);
      if (index > maxIndex) maxIndex = index;
    }

    return complexityOrder[maxIndex];
  }

public getReason(notation: ComplexityProfile, signals: SignalProfile): string {
    const reasons = this.getAllReasons(notation, signals);

    if (reasons.length === 0) {
      return "Complexity determined by signal analysis";
    }

    // Pick one randomly to keep users engaged (weighted by priority)
    return this._weightedRandomSelect(reasons);
  }

public getAllReasons(notation: ComplexityProfile, signals: SignalProfile): string[] {
    const timeReasons = this._getMatchingReasons(
      notation.timeNotation,
      signals,
      "time"
    );

    const spaceReasons = this._getMatchingReasons(
      notation.spaceNotation,
      signals,
      "space"
    );

    // Combine and deduplicate
    const allReasons = [...timeReasons, ...spaceReasons];
    return [...new Set(allReasons)];
  }

private getTimeReasons(notation: string, signals: SignalProfile): string[] {
    return this._getMatchingReasons(notation, signals, "time");
  }

private getSpaceReasons(notation: string, signals: SignalProfile): string[] {
    return this._getMatchingReasons(notation, signals, "space");
  }

private _getMatchingReasons(
    notation: string,
    signals: SignalProfile,
    type: "time" | "space"
  ): string[] {
    const rulesForNotation = COMPLEXITY_REASONS[type][notation];

    if (!rulesForNotation || rulesForNotation.length === 0) {
      return [];
    }

    // Filter rules where condition passes
    const matchingRules = rulesForNotation.filter((rule) =>
      rule.condition(signals)
    );

    // Sort by priority (descending) then extract reasons
    const sortedRules = matchingRules.sort(
      (a, b) => (b.priority || 1) - (a.priority || 1)
    );

    return sortedRules.map((rule) => rule.reason);
  }

private _weightedRandomSelect(reasons: string[]): string {
    if (reasons.length === 0) return "Complexity determined by signal analysis";
    if (reasons.length === 1) return reasons[0];

    // For simplicity, just pick randomly from top 3 highest priority
    const topReasons = reasons.slice(0, Math.min(3, reasons.length));
    return topReasons[Math.floor(Math.random() * topReasons.length)];
  }

public getDetailedBreakdown(notation: ComplexityProfile, signals: SignalProfile): {
    time: { notation: string; reasons: string[] };
    space: { notation: string; reasons: string[] };
  } {
    return {
      time: {
        notation: notation.timeNotation,
        reasons: this.getTimeReasons(notation.timeNotation, signals)
      },
      space: {
        notation: notation.spaceNotation,
        reasons: this.getSpaceReasons(notation.spaceNotation, signals)
      }
    };
  }

public run(
    node: Node,
    functionName: string | null,
    keywordSet: Set<string>
  ): { success: boolean; result?: ComplexityResult; message: string } {

    try {
      // 1. Single AST pass — collect every raw signal we care about
      const signals = this.extractSignals(node, functionName);

      // 2. Map raw signals → named Big-O categories + numeric scores
      const profile = this.buildComplexityProfile(signals);

      // 2b. Generate human-readable reasons for the detected complexity
      const reasons = this.generateComplexityReason(profile, signals);

      // 3. Combine time + space into a unified growth object
      const growth = this.modelGrowth(profile);

      // 4. Attach total score and risk tier
      const composed = this.composeGrowth(growth);

      // 5. Format and return the final ComplexityResult
      const result = this.buildResult(node, reasons, functionName, composed);

      return { success: true, result, message: "Complexity calculated" };

    } catch (err) {
      return { success: false, message: (err as Error).message };
    }
  }

private extractSignals(
    node: Node,
    functionName: string | null
  ): SignalProfile {

    // Get the full text for regex analysis
    const fullText = node.getText();

    // ── Mutable counters ────────────────────────────────────────────────────
    let loops = 0;
    let maxLoopDepth = 0;          // deepest nesting seen
    let conditionals = 0;
    let recursion = false;
    let recursionCallCount = 0;    // total recursive call-sites found
    let recursionDoubled = false;
    let hasBreakOrContinue = false;
    let hasEarlyReturn = false;
    let conditionDoubled = false;
    let allocations = 0;
    let variables = 0;
    let usesDataStructures = false;
    let usesNestedDataStructures = false;
    let loopWithAllocation = false;
    let recursionWithAllocation = false;
    let hasLoopInRecursion = false;
    let hasFilterOrSlice = false;

    // NEW: Additional signals from regex analysis
    let hasLinearSearchInLoop = false;
    let hasNestedArrayMethods = false;
    let hasSorting = false;
    let hasJSONOperations = false;
    let hasSpreadOperator = false;
    let functionalLoopCount = 0;

    // ── Stack to track current loop-nesting depth ───────────────────────────
    let currentLoopDepth = 0;

    // ── Helpers ─────────────────────────────────────────────────────────────

    /** Returns true if `callNode` is a direct self-call of functionName. */
    const isSelfCall = (callNode: CallExpression): boolean => {
      if (!functionName) return false;
      const expr = callNode.getExpression();
      return expr.getText() === functionName;
    };

    /** Returns true if the node is any kind of memory allocation. */
    const isAllocation = (n: Node): boolean => {
      if (n.getKind() === SyntaxKind.NewExpression) return true;
      if (n.getKind() === SyntaxKind.ArrayLiteralExpression) return true;
      if (n.getKind() === SyntaxKind.ObjectLiteralExpression) return true;
      // Array(), Map(), Set() constructor-style calls
      if (n.getKind() === SyntaxKind.CallExpression) {
        const name = (n as CallExpression).getExpression().getText();
        return ALLOCATION_CONSTRUCTOR_NAMES.has(name);
      }
      return false;
    };

    // ── Recursive DFS traversal ─────────────────────────────────────────────
    const traverse = (n: Node, insideLoop: boolean, insideRecursion: boolean): void => {

      const kind = n.getKind();

      // ── LOOP detection ─────────────────────────────────────────────────
      if (LOOP_KINDS.has(kind)) {
        loops++;
        currentLoopDepth++;
        maxLoopDepth = Math.max(maxLoopDepth, currentLoopDepth);
        insideLoop = true;

        // Track if we're in a loop inside a recursive function
        if (insideRecursion) hasLoopInRecursion = true;
      }

      // ── CONDITIONAL detection ──────────────────────────────────────────
      if (
        kind === SyntaxKind.IfStatement ||
        kind === SyntaxKind.SwitchStatement ||
        kind === SyntaxKind.ConditionalExpression
      ) {
        conditionals++;
      }

      // ── COMPOUND CONDITION detection (&&, ||) ──────────────────────────
      if (kind === SyntaxKind.BinaryExpression) {
        const op = n.getChildAtPos(1)?.getText();
        if (op === "&&" || op === "||") conditionDoubled = true;
      }

      // ── BREAK / CONTINUE detection ─────────────────────────────────────
      if (
        kind === SyntaxKind.BreakStatement ||
        kind === SyntaxKind.ContinueStatement
      ) {
        hasBreakOrContinue = true;
      }

      // ── EARLY RETURN detection (inside loops) ──────────────────────────
      if (kind === SyntaxKind.ReturnStatement && insideLoop) {
        hasEarlyReturn = true;
      }

      // ── VARIABLE DECLARATION detection ────────────────────────────────
      if (
        kind === SyntaxKind.VariableDeclaration ||
        kind === SyntaxKind.Parameter
      ) {
        variables++;
      }

      // ── ALLOCATION detection ───────────────────────────────────────────
      if (isAllocation(n)) {
        allocations++;

        // If we're allocating inside a loop → O(n) space at minimum
        if (insideLoop) loopWithAllocation = true;

        // If we're allocating inside a recursive branch → O(n) stack space
        if (insideRecursion) recursionWithAllocation = true;

        // Check for nested data structures (Array of Array, Map of Map, etc.)
        if (kind === SyntaxKind.NewExpression || kind === SyntaxKind.ArrayLiteralExpression) {
          n.forEachChild(child => {
            if (isAllocation(child)) usesNestedDataStructures = true;
          });
        }

        usesDataStructures = true;
      }

      // ── FILTER/SLICE detection (factorial pattern indicator) ───────────
      if (kind === SyntaxKind.CallExpression) {
        const callNode = n as CallExpression;
        const callText = callNode.getExpression().getText();

        if (callText.includes("filter") || callText.includes("slice")) {
          hasFilterOrSlice = true;
        }
      }

      // ── RECURSIVE CALL detection ───────────────────────────────────────
      if (kind === SyntaxKind.CallExpression) {
        const callNode = n as CallExpression;
        if (isSelfCall(callNode)) {
          recursion = true;
          recursionCallCount++;
          insideRecursion = true;
        }
      }

      // ── DOUBLED RECURSION (e.g. return f(n-1) + f(n-2)) ───────────────
      // We count self-calls per BinaryExpression scope.
      // If any binary expression contains ≥ 2 recursive calls, it's O(2ⁿ).
      if (kind === SyntaxKind.BinaryExpression) {
        let selfCallsInExpr = 0;
        n.forEachDescendant(desc => {
          if (
            desc.getKind() === SyntaxKind.CallExpression &&
            isSelfCall(desc as CallExpression)
          ) selfCallsInExpr++;
        });
        if (selfCallsInExpr >= 2) recursionDoubled = true;
      }

      // ── Recurse into children ──────────────────────────────────────────
      n.forEachChild(child => traverse(child, insideLoop, insideRecursion));

      // ── Unwind loop depth on exit ──────────────────────────────────────
      if (LOOP_KINDS.has(kind)) {
        currentLoopDepth--;
      }
    };

    traverse(node, false, false);

    // ═══════════════════════════════════════════════════════════════════════
    // REGEX FALLBACK ANALYSIS
    // Use when AST analysis might miss patterns or needs supplementation
    // ═══════════════════════════════════════════════════════════════════════

    // ── FUNCTIONAL LOOP DETECTION (forEach, map, filter, reduce) ──────────
    const functionalLoopMatches = fullText.match(/\.(forEach|map|filter|reduce)\s*\(/g);
    if (functionalLoopMatches) {
      functionalLoopCount = functionalLoopMatches.length;
      // Add to loop count if AST missed them
      const totalDetectedLoops = loops + functionalLoopCount;
      if (totalDetectedLoops > loops) {
        loops = totalDetectedLoops;
      }
    }

    // ── NESTED ARRAY METHODS (map inside map, filter with includes, etc) ──
    const nestedArrayPattern = /\.(map|filter|forEach|reduce)\s*\([^)]*\.(map|filter|includes|indexOf|find|findIndex)/;
    hasNestedArrayMethods = nestedArrayPattern.test(fullText);

    // If we found nested array methods, update nesting depth
    if (hasNestedArrayMethods && maxLoopDepth < 2) {
      maxLoopDepth = Math.max(maxLoopDepth, 2);
    }

    // ── LINEAR SEARCH IN LOOPS (.includes, .indexOf inside loops) ─────────
    // This is a critical O(n²) pattern that's easy to miss
    const hasLinearSearchMethods = /\.(includes|indexOf|find|findIndex)\s*\(/.test(fullText);
    if ((loops > 0 || functionalLoopCount > 0) && hasLinearSearchMethods) {
      hasLinearSearchInLoop = true;
    }

    // ── BINARY RECURSION FALLBACK ─────────────────────────────────────────
    // If AST missed it, use regex to detect multiple recursive calls
    if (functionName && !recursionDoubled && recursion) {
      const recursiveCallPattern = new RegExp(`\\b${functionName}\\s*\\(`, 'g');
      const callsInBinaryExpr = fullText.match(/return[^;]*\+[^;]*|return[^;]*\*[^;]*/g);

      if (callsInBinaryExpr) {
        for (const expr of callsInBinaryExpr) {
          const callsInExpr = (expr.match(recursiveCallPattern) || []).length;
          if (callsInExpr >= 2) {
            recursionDoubled = true;
            break;
          }
        }
      }
    }

    // ── SORTING DETECTION ──────────────────────────────────────────────────
    hasSorting = /\.sort\s*\(/.test(fullText);

    // ── JSON OPERATIONS (expensive builtins) ───────────────────────────────
    hasJSONOperations = /JSON\.(parse|stringify)/.test(fullText);

    // ── SPREAD OPERATOR (creates copies) ───────────────────────────────────
    hasSpreadOperator = /\.\.\.|\bspread\b/.test(fullText);

    // ── ENHANCED NESTING DEPTH (regex fallback) ────────────────────────────
    // Use regex-based nesting calculation if it's higher than AST found
    const regexNestingDepth = this.estimateLoopNestingDepth(fullText);
    maxLoopDepth = Math.max(maxLoopDepth, regexNestingDepth);

    // ── Post-traversal derived booleans ────────────────────────────────────
    const isConstantBody = loops === 0 && !recursion;
    const isConstantWithReturn =
      isConstantBody && conditionals === 0 && allocations === 0;

    // ── Dataset size hint ──────────────────────────────────────────────────
    const allText = fullText.toLowerCase();
    let dataSizeHint: "SMALL" | "MEDIUM" | "LARGE" = "MEDIUM";
    if (/\b(n|size|length|count|items|dataset|records|rows|elements)\b/.test(allText)) {
      dataSizeHint = "LARGE";
    } else if (/\b(limit|page|chunk|batch|slice|offset)\b/.test(allText)) {
      dataSizeHint = "MEDIUM";
    } else if (isConstantBody) {
      dataSizeHint = "SMALL";
    }

    return {
      loops,
      nestedLoops: maxLoopDepth,
      conditionals,
      recursion,
      recursionDoubled,
      hasBreakOrContinue,
      hasEarlyReturn,
      conditionDoubled,
      isConstantBody,
      isConstantWithReturn,
      allocations,
      variables,
      usesDataStructures,
      usesNestedDataStructures,
      loopWithAllocation,
      recursionWithAllocation,
      hasLoopInRecursion,
      hasFilterOrSlice,
      dataSizeHint,
      // NEW SIGNALS FROM REGEX ANALYSIS
      hasLinearSearchInLoop,
      hasNestedArrayMethods,
      hasSorting,
      hasJSONOperations,
      hasSpreadOperator,
      functionalLoopCount,
    };
  }

private estimateLoopNestingDepth(text: string): number {
    let maxDepth = 0;
    let currentDepth = 0;
    const blockStack: boolean[] = [];

    const lines = text.split('\n');

    for (let line of lines) {
      // Remove strings and comments (basic heuristic)
      line = line.replace(/\/\/.*$/g, ''); // remove single-line comments
      line = line.replace(/\/\*.*\*\//g, ''); // remove block comments
      line = line.replace(/(["'`]).*?\1/g, ''); // remove string literals

      // Count all loop keywords in the line
      const loopKeywords = line.match(/\b(for|while|do|forEach|map|filter|reduce)\b/g) || [];
      const openBraces = (line.match(/\{/g) || []).length;
      const closeBraces = (line.match(/\}/g) || []).length;

      // Handle loop keywords
      for (let i = 0; i < loopKeywords.length; i++) {
        blockStack.push(true);
        currentDepth++;
        maxDepth = Math.max(maxDepth, currentDepth);
      }

      // Track non-loop blocks for extra braces
      const nonLoopBlocks = Math.max(0, openBraces - loopKeywords.length);
      for (let i = 0; i < nonLoopBlocks; i++) {
        blockStack.push(false);
      }

      // Close blocks
      for (let i = 0; i < closeBraces; i++) {
        const isLoopBlock = blockStack.pop();
        if (isLoopBlock) {
          currentDepth = Math.max(0, currentDepth - 1);
        }
      }
    }

    return maxDepth;
  }

private buildComplexityProfile(signals: SignalProfile): ComplexityProfile {

    // ── TIME COMPLEXITY ────────────────────────────────────────────────────

    let timeNotation: ComplexityNotation;
    let timeScore: number;

    if (signals.isConstantWithReturn) {
      // No branching, no loops, immediate return — provably O(1)
      timeNotation = "O(1)";
      timeScore = 1;

    } else if (signals.isConstantBody && signals.conditionals > 0) {
      // Conditionals only (no loops/recursion) — still O(1) at runtime
      timeNotation = "O(1)";
      timeScore = 1;

    } else if (signals.recursionDoubled) {
      // Two recursive calls per frame → exponential blowup O(2ⁿ)
      timeNotation = "O(2ⁿ)";
      timeScore = 9;

    } else if (signals.recursion && signals.hasLoopInRecursion && signals.hasFilterOrSlice) {
      // Factorial pattern: recursion + loop + filtering remaining elements
      // Classic permutation/combination generation
      timeNotation = "O(n!)";
      timeScore = 10;

    } else if (signals.hasLinearSearchInLoop || signals.hasNestedArrayMethods) {
      // CRITICAL: Linear search inside loops or nested array methods
      // This is a hidden O(n²) pattern that's very common
      timeNotation = "O(n²)";
      timeScore = 7;

    } else if (signals.recursion && signals.nestedLoops >= 2) {
      // Recursive + deeply nested loops → very expensive, treat as O(n³)
      timeNotation = "O(n³)";
      timeScore = 8;

    } else if (signals.recursion && signals.hasLoopInRecursion) {
      // Recursion with a loop inside → likely O(n²)
      timeNotation = "O(n²)";
      timeScore = 7;

    } else if (signals.recursion && signals.allocations > 0) {
      // Recursion with allocations (like merge sort with slice)
      // If it's dividing the problem, it's likely O(n log n)

      if (signals.hasFilterOrSlice) {
        timeNotation = "O(n log n)";
        timeScore = 5;
      } else {
        timeNotation = "O(n²)";
        timeScore = 7;
      }

    } else if (signals.hasSorting) {
      // Sorting is O(n log n) - common pattern
      timeNotation = "O(n log n)";
      timeScore = 5;

    } else if (signals.recursion) {
      // Pure recursion (single branch) → O(n) on the call stack
      timeNotation = "O(n)";
      timeScore = 4;

    } else if (signals.nestedLoops >= 3) {
      // Triple-nested loop → O(n³)
      timeNotation = "O(n³)";
      timeScore = 8;

    } else if (signals.nestedLoops === 2) {
      // Double-nested loop → O(n²)
      timeNotation = "O(n²)";
      timeScore = 7;

    } else if (signals.loops > 0) {
      // Single loop. Check for logarithmic patterns:
      // - Has conditionals AND (break/continue OR early return)
      // - Single loop only
      const likelyLogN =
        signals.conditionals > 0 &&
        (signals.hasBreakOrContinue || signals.hasEarlyReturn) &&
        signals.loops === 1;

      timeNotation = likelyLogN ? "O(log n)" : "O(n)";
      timeScore = likelyLogN ? 2 : 4;

    } else {
      // Fallback: no identifiable growth pattern → O(1)
      timeNotation = "O(1)";
      timeScore = 1;
    }

    // ── SPACE COMPLEXITY ───────────────────────────────────────────────────

    let spaceNotation: ComplexityNotation;
    let spaceScore: number;

    if (signals.usesNestedDataStructures) {
      // Nested data structures (array of arrays, map of maps) → O(n²) space
      spaceNotation = "O(n²)";
      spaceScore = 7;

    } else if (signals.hasSpreadOperator && signals.loops > 0) {
      // Spread operator in loops creates multiple copies → O(n) or O(n²)
      spaceNotation = signals.nestedLoops >= 2 ? "O(n²)" : "O(n)";
      spaceScore = signals.nestedLoops >= 2 ? 7 : 4;

    } else if (signals.recursionWithAllocation || signals.loopWithAllocation) {
      // Allocating inside a loop or recursion → grows with input → O(n)
      spaceNotation = "O(n)";
      spaceScore = 4;

    } else if (signals.recursion) {
      // Recursion alone creates an implicit call stack → O(n) space
      spaceNotation = "O(n)";
      spaceScore = 4;

    } else if (signals.hasJSONOperations) {
      // JSON operations create full copies of data → O(n) space
      spaceNotation = "O(n)";
      spaceScore = 4;

    } else if (signals.allocations > 0 || signals.usesDataStructures || signals.hasSpreadOperator) {
      // Fixed allocations outside loops → O(1) auxiliary, but flag it
      spaceNotation = "O(1)";
      spaceScore = 2;

    } else {
      // No allocations detected → O(1)
      spaceNotation = "O(1)";
      spaceScore = 1;
    }

    return { timeNotation, spaceNotation, timeScore, spaceScore };
  }

private generateComplexityReason(
    profile: ComplexityProfile,
    signals: SignalProfile
  ): ComplexityReason[] {

    const breakdown = this.aiExplain.getDetailedBreakdown(profile, signals);

    const reasons: ComplexityReason[] = [];

    // TIME reasons
    for (const r of breakdown.time.reasons) {
      reasons.push({
        type: "time",
        detail: r || r,
        impact: this.mapImpact(profile.timeScore),
        confidence: 85,
      });
    }

    // SPACE reasons
    for (const r of breakdown.space.reasons) {
      reasons.push({
        type: "space",
        detail: r || r,
        impact: this.mapImpact(profile.spaceScore),
        confidence: 85,
      });
    }

    return reasons;
  }

private mapImpact(score: number): Lowercase_RiskLevelType {
    if (score <= 3) return "low";
    if (score <= 6) return "medium";
    if (score <= 8) return "high";
    return "critical";
  }

private modelGrowth(profile: ComplexityProfile): GrowthProfile {

    // Weighted combination: time is weighted more heavily than space
    const totalScore = Math.round(profile.timeScore * 0.7 + profile.spaceScore * 0.3);

    return {
      time: profile.timeNotation,
      space: profile.spaceNotation,
      timeScore: profile.timeScore,
      spaceScore: profile.spaceScore,
      totalScore,
      riskLevel: this.scoreToRisk(totalScore),
    };
  }

private composeGrowth(growth: GrowthProfile): GrowthProfile {

    // Clamp totalScore to [1, 10]
    const totalScore = Math.min(10, Math.max(1, growth.totalScore));

    return {
      ...growth,
      totalScore,
      riskLevel: this.scoreToRisk(totalScore),
    };
  }

private buildResult(
    node: Node,
    reasons: ComplexityReason[],
    functionName: string | null,
    data: GrowthProfile
  ): ComplexityResult {

    // Confidence is inversely proportional to score uncertainty.
    // High-risk scores have more heuristic assumptions → lower confidence.
    const confidence = data.totalScore <= 3 ? 90 :
      data.totalScore <= 6 ? 80 : 70;

    return {
      id: crypto.randomUUID(),

      kind: "functions",

      name: functionName,

      startLine: node.getStartLineNumber(),
      endLine: node.getEndLineNumber(),

      text: node.getText(),

      timeComplexity: { notation: data.time, confidence: 0, flags: ["not implemented"] },
      spaceComplexity: { notation: data.space, confidence: 0, flags: ["not implemented"] },

      timeScore: data.timeScore,
      spaceScore: data.spaceScore,
      totalScore: data.totalScore,

      riskLevel: data.riskLevel,

      matchedKeywords: [],
      reasons: reasons,

      tierUsed: "paid",

      confidence,
    };
  }

private scoreToRisk(score: number): Risk {
    if (score <= 3) return "LOW";
    if (score <= 6) return "MEDIUM";
    return "HIGH";
  }

static calculateTimeComplexity(
    loopDepth: number,
    hasRecursion: boolean,
    isBinaryRecursion: boolean,
    hasSorting: boolean,
    hasLinearSearch: boolean
  ): CalculatorComplexityResult {

    const flags: string[] = [];
    let confidence = 100;

    // 1. Explosive growth dominates everything
    if (isBinaryRecursion) {
      flags.push("BINARY_RECURSION");
      return {
        notation: "O(2^n)",
        confidence: 90,
        flags
      };
    }

    // 2. High-order polynomial (unknown exponent)
    if (loopDepth >= 2 && hasRecursion) {
      flags.push("RECURSION", "NESTED_LOOPS");
      confidence -= 30;

      return {
        notation: "O(n^k)",
        confidence,
        flags
      };
    }

    if (loopDepth >= 2) {
      flags.push("NESTED_LOOPS");
      confidence -= 20;

      return {
        notation: "O(n^k)",
        confidence,
        flags
      };
    }

    // 3. Superlinear
    if (hasSorting) {
      flags.push("SORTING_PATTERN");
      confidence -= 15;

      return {
        notation: "O(n log n)",
        confidence,
        flags
      };
    }

    // 4. Linear
    if (loopDepth === 1 || hasLinearSearch || hasRecursion) {
      flags.push("LINEAR_ITERATION");
      confidence -= hasRecursion ? 20 : 0;

      return {
        notation: "O(n)",
        confidence,
        flags
      };
    }

    // 5. Constant
    return {
      notation: "O(1)",
      confidence: 95,
      flags
    };
  }

static calculateSpaceComplexity(
    allocationsInLoop: number, hasRecursion: boolean, _maxLoopDepth: number, hasDeepClone: boolean, hasAccumulation: boolean): CalculatorComplexityResult {

    const flags: string[] = [];
    let confidence = 100;

    // Recursion → stack growth (linear upper bound)
    if (hasRecursion) {
      flags.push("RECURSION_STACK");
      confidence -= 25;

      return {
        notation: "O(n)",
        confidence,
        flags
      };
    }

    // Accumulation or cloning → heap growth
    if (hasAccumulation || hasDeepClone) {
      flags.push("HEAP_ACCUMULATION");
      confidence -= 20;

      return {
        notation: "O(n)",
        confidence,
        flags
      };
    }

    // Allocations inside loop (escape unknown)
    if (allocationsInLoop > 0) {
      flags.push("LOOP_ALLOCATIONS");
      confidence -= 30;

      return {
        notation: "UNKNOWN",
        confidence,
        flags
      };
    }

    // Constant space
    return {
      notation: "O(1)",
      confidence: 95,
      flags
    };
  }

static determineRiskLevel(totalScore: number): Uppercase_RiskLevelType {
    if (totalScore >= RISK_THRESHOLDS.CRITICAL) return "CRITICAL";
    if (totalScore >= RISK_THRESHOLDS.HIGH) return "HIGH";
    if (totalScore >= RISK_THRESHOLDS.MEDIUM) return "MEDIUM";
    return "LOW";
  }

static calculateOverallConfidence(reasons: ComplexityReason[]): number {
    if (reasons.length === 0) return 50;

    // Take the strongest signal, not the average
    return Math.max(...reasons.map(r => r.confidence));
  }

constructor(keywordSet: Set<string>, enhancedAnalyzer: EnhancedAnalyzer_v2) {
    this.keywordSet = keywordSet;
    this.enhancedAnalyzer = enhancedAnalyzer
  }

export class PaidTierComplexityCalculator {


  static calculateTimeComplexity(
    loopDepth: number,
    hasRecursion: boolean,
    isBinaryRecursion: boolean,
    hasSorting: boolean,
    hasLinearSearch: boolean,
    hasDeepClone: boolean,
    hasAccumulation: boolean
  ): CalculatorComplexityResult {
    const flags: string[] = [];

    // --- 1. FACTORIAL GROWTH (O(n!)) ---
    // Recursion combined with loops or permutations
    if (hasRecursion && loopDepth >= 1 && (hasSorting || isBinaryRecursion)) {
      flags.push("FACTORIAL_EXPLOSION");
      return { notation: "O(n!)", confidence: 70, flags };
    }

    // --- 2. EXPONENTIAL GROWTH (O(2^n)) ---
    if (isBinaryRecursion || (hasRecursion && hasDeepClone)) {
      flags.push("EXPONENTIAL_RECURSION");
      return { notation: "O(2^n)", confidence: 85, flags };
    }

    // --- 3. UNKNOWN HIGH POLYNOMIAL (O(n^k)) ---
    // Depth 4+ is usually the threshold where we stop precise naming
    if (loopDepth >= 4) {
      flags.push("DEEP_NESTING_EXCESSIVE");
      return { notation: "O(n^k)", confidence: 90, flags };
    }

    // --- 4. CUBIC GROWTH (O(n³)) ---
    // Depth 3, or Depth 2 with heavy operations like sorting
    if (loopDepth === 3 || (loopDepth === 2 && hasSorting)) {
      flags.push("CUBIC_COMPLEXITY");
      return { notation: "O(n³)", confidence: 80, flags };
    }

    // --- 5. QUADRATIC GROWTH (O(n²)) ---
    // Depth 2, or Depth 1 with Linear Search/Sorting/Deep Clone
    if (loopDepth === 2) {
      flags.push("NESTED_LOOPS");
      return { notation: "O(n²)", confidence: 95, flags };
    }

    if (loopDepth === 1 && (hasLinearSearch || hasSorting || hasDeepClone)) {
      flags.push("SEARCH_OR_SORT_IN_LOOP");
      // O(n * log n) or O(n * n) both map here for safety
      return { notation: "O(n²)", confidence: 85, flags };
    }

    // --- 6. SUPERLINEAR (O(n log n)) ---
    if (hasSorting) {
      flags.push("SORTING_ALGORITHM");
      return { notation: "O(n log n)", confidence: 95, flags };
    }

    // --- 7. LINEAR (O(n)) ---
    if (loopDepth === 1 || hasLinearSearch || hasRecursion || hasAccumulation) {
      if (hasRecursion) flags.push("RECURSIVE_WALK");
      if (hasAccumulation) flags.push("ACCUMULATION_PATTERN");
      flags.push("LINEAR_SCAN");

      return {
        notation: "O(n)",
        confidence: hasRecursion ? 75 : 90,
        flags
      };
    }

    // --- 8. CONSTANT (O(1)) ---
    // If no loops, no recursion, and no linear operations found
    return {
      notation: "O(1)",
      confidence: 95,
      flags
    };
  }



  /**
  * SPACE COMPLEXITY — Analyzes Stack and Heap growth patterns
  */
  static calculateSpaceComplexity(
    loopDepth: number,
    allocationInLoop: number,
    hasRecursion: boolean,
    hasSorting: boolean,
    hasDeepClone: boolean,
    hasAccumulation: boolean
  ): CalculatorComplexityResult {
    const flags: string[] = [];

    // --- 1. QUADRATIC SPACE (O(n²)) ---
    // Deep cloning or Accumulation inside a loop creates a 2D data growth pattern
    if (loopDepth >= 1 && (hasDeepClone || hasAccumulation)) {
      flags.push("NESTED_ALLOCATION");
      return {
        notation: "O(n²)",
        confidence: 80,
        flags
      };
    }

    // --- 2. LINEAR SPACE (O(n)) ---
    // Recursion causes stack growth. Accumulation/Cloning causes heap growth.
    if (hasRecursion || hasAccumulation || hasDeepClone) {
      if (hasRecursion) flags.push("STACK_RECURSION");
      if (hasAccumulation) flags.push("HEAP_GROWTH");
      if (hasDeepClone) flags.push("OBJECT_CLONING");

      return {
        notation: "O(n)",
        // Recursion depth is an estimate, so lower confidence slightly
        confidence: hasRecursion ? 75 : 90,
        flags
      };
    }

    // --- 3. UNKNOWN / VOLATILE ---
    // If we see generic allocations in a loop but no specific pattern
    if (allocationInLoop > 0) {
      flags.push("LOOP_ALLOCATIONS");
      return {
        notation: "O(n^k)", // Mapping "Unknown" to "n^k" to match your allowed types
        confidence: 60,
        flags
      };
    }

    // --- 4. LOGARITHMIC SPACE (O(log n)) ---
    // Sorting (e.g., QuickSort) typically uses O(log n) stack space
    if (hasSorting) {
      flags.push("SORT_STACK_USAGE");
      return {
        notation: "O(log n)",
        confidence: 85,
        flags
      };
    }

    // --- 5. CONSTANT SPACE (O(1)) ---
    return {
      notation: "O(1)",
      confidence: 95,
      flags
    };
  }


  static determineRiskLevel(totalScore: number): Uppercase_RiskLevelType {
    if (totalScore >= RISK_THRESHOLDS.CRITICAL) return "CRITICAL";
    if (totalScore >= RISK_THRESHOLDS.HIGH) return "HIGH";
    if (totalScore >= RISK_THRESHOLDS.MEDIUM) return "MEDIUM";
    return "LOW";
  }

  /**
   * Confidence aggregation — no averaging
   */
  static calculateOverallConfidence(signals: ASTSignals): number {
    let confidence = 100;

    if (signals.maxLoopDepth > 0) {
      confidence -= WEIGHTS.LOOP;
      confidence -= signals.maxLoopDepth * WEIGHTS.NESTED_LOOP_FACTOR;
    }

    if (signals.hasRecursion) {
      confidence -= signals.isBinaryRecursion
        ? WEIGHTS.BINARY_RECURSION
        : WEIGHTS.RECURSION;
    }

    if (signals.hasSorting) confidence -= WEIGHTS.SORT;
    if (signals.hasLinearSearch) confidence -= WEIGHTS.SEARCH_LINEAR;

    confidence -= signals.allocationsInLoop * WEIGHTS.ALLOCATION;

    if (signals.hasDeepClone) confidence -= WEIGHTS.DEEP_CLONE;
    if (signals.hasAccumulation) confidence -= WEIGHTS.ACCUMULATOR;

    confidence -= signals.matchedKeywords.length * WEIGHTS.KEYWORD_HIT;

    return Math.max(0, Math.min(100, Math.round(confidence)));
  }

}

